"""Symbolic type visitors: harness layout and the strict inverse reader.

`MainBuilder` owns the numbering contract for an entry's own symbolic harness.
It follows the classic convention: inputs in parameter order, then the
non-void result, starting at `x0`; every visited bool, char, int, enum, string
buffer, array or struct reserves one increasing `xN`.  Scalars own exactly one
object; composites reserve an identifier of their own that never appears in a
recorded test, and then their children in order.  `String(N)` reserves its
buffer identifier followed by `N` character objects.  Aliases reserve nothing
and add no path component.  `ResultReader` is the strict inverse: every
expected object must occur exactly once with exactly its width.
"""
from .ast import (Alias, Array, Bool, Char, Enum, Int, String, Struct, Void,
                  underlying, int_width)
from .errors import InvalidCampaign

_SCALARS = (Bool, Char, Int, Enum)

# A documented campaign reserves at most 65536 identifiers across all entry
# plans; the ceiling below only exists so that an out-of-domain layout cannot
# exhaust memory or time before the pipeline notices.
MAX_RESERVED = 1 << 17


def _size(type, memo, limit):
    """Identifiers reserved by one type; None when the layout is absurd."""
    while isinstance(type, Alias):
        type = type.type
    name = type.decl
    if name is not None and name in memo:
        return memo[name]
    if isinstance(type, _SCALARS):
        value = 1
    elif isinstance(type, String):
        value = 1 + type.maxsize
    elif isinstance(type, Void):
        value = 0
    elif isinstance(type, Array):
        inner = _size(type.element_type, memo, limit)
        if inner is None:
            return None
        value = 1 + type.size * inner
    elif isinstance(type, Struct):
        value = 1
        for field in type.fields.values():
            inner = _size(field, memo, limit)
            if inner is None:
                return None
            value += inner
    else:
        raise InvalidCampaign("unsupported symbolic type")
    if value > limit:
        return None
    if name is not None:
        memo[name] = value
    return value


def reserved_ids(type, limit=MAX_RESERVED):
    """Total identifiers a type reserves, or None above `limit`."""
    return _size(type, {}, limit)


class Harness(object):
    """The symbolic harness of a single entry."""

    __slots__ = ("entry", "slots", "leaves", "flag", "variables", "inputs",
                 "result", "param_names")

    def __init__(self, entry, slots, leaves, flag, variables, inputs, result):
        self.entry = entry
        self.slots = slots          # list of [name, path, width]
        self.leaves = leaves        # name -> (width, kind, payload)
        self.flag = flag            # name or None
        self.variables = variables
        self.inputs = inputs        # list of (name, descriptor)
        self.result = result        # (name, descriptor) or None
        self.param_names = [name for name, _ in inputs]


class MainBuilder(object):
    """Number the symbolic objects of one entry harness."""

    def __init__(self):
        self.slots = []
        self.leaves = {}
        self.number = 0

    def _next(self):
        index = self.number
        if index > MAX_RESERVED:
            raise InvalidCampaign("symbolic harness too large")
        self.number = index + 1
        return "x%d" % index

    def _scalar(self, kind, width, payload, path):
        name = self._next()
        self.slots.append([name, list(path), width])
        self.leaves[name] = (width, kind, payload)
        return (kind, name, payload)

    def _visit(self, type, path):
        """Reserve identifiers for `type` at `path`; returns a descriptor."""
        while isinstance(type, Alias):
            type = type.type
        if isinstance(type, (Bool, Char, Int, Enum)):
            if isinstance(type, Bool):
                return self._scalar("bool", 1, None, path)
            if isinstance(type, Char):
                return self._scalar("char", 1, None, path)
            if isinstance(type, Int):
                return self._scalar("int", int_width(type.bits), type, path)
            return self._scalar("enum", 4, tuple(type.values), path)
        if isinstance(type, String):
            self._next()                       # the string buffer identifier
            names = []
            for index in range(type.maxsize):
                name = self._next()
                names.append(name)
                self.slots.append([name, path + [index], 1])
                self.leaves[name] = (1, "char", None)
            return ("string", tuple(names))
        if isinstance(type, Array):
            self._next()                       # the aggregate identifier
            children = tuple(self._visit(type.element_type, path + [index])
                             for index in range(type.size))
            return ("array", children)
        if isinstance(type, Struct):
            self._next()                       # the aggregate identifier
            children = tuple((field, self._visit(ftype, path + [field]))
                             for field, ftype in type.fields.items())
            return ("struct", children)
        if isinstance(type, Void):
            return ("void", None)
        raise InvalidCampaign("unsupported symbolic type")

    def build(self, module, flag_needed):
        memo = {}
        budget = 0
        for _, type in module.params:
            size = _size(type, memo, MAX_RESERVED)
            if size is None:
                raise InvalidCampaign("symbolic harness too large")
            budget += size
        result_name, result_type = module.result
        has_result = not isinstance(underlying(result_type), Void)
        if has_result:
            size = _size(result_type, memo, MAX_RESERVED)
            if size is None:
                raise InvalidCampaign("symbolic harness too large")
            budget += size
        if flag_needed:
            budget += 1
        if budget > MAX_RESERVED:
            raise InvalidCampaign("symbolic harness too large")
        inputs = []
        for name, type in module.params:
            inputs.append((name, self._visit(type, [name])))
        result = None
        if has_result:
            result = (result_name, self._visit(result_type, [result_name]))
        flag = None
        if flag_needed:
            flag = self._next()
            self.leaves[flag] = (1, "flag", None)
        return Harness(module.name, self.slots, self.leaves, flag, self.number,
                       inputs, result)


def build_harness(module, flag_needed):
    return MainBuilder().build(module, flag_needed)


class ResultReader(object):
    """Read recovered values out of a validated object assignment."""

    __slots__ = ("objects",)

    def __init__(self, objects):
        self.objects = objects

    def read(self, descriptor):
        return read_value(descriptor, self.objects)


def read_value(descriptor, objects):
    """Materialise one recovered value from the object assignment."""
    kind = descriptor[0]
    if kind == "int":
        return objects[descriptor[1]]
    if kind == "bool":
        return objects[descriptor[1]] == 1
    if kind == "char":
        return chr(objects[descriptor[1]])
    if kind == "enum":
        return descriptor[2][objects[descriptor[1]]]
    if kind == "string":
        pieces = []
        for name in descriptor[1]:
            code = objects[name]
            if code == 0:
                break
            pieces.append(chr(code))
        return "".join(pieces)
    if kind == "array":
        return [read_value(child, objects) for child in descriptor[1]]
    if kind == "struct":
        return {field: read_value(child, objects)
                for field, child in descriptor[1]}
    return None
